body.script:
/* Default application template. This source is stored in the newly created root JSON entry. */
export async function main(db, mount) {
  const css = document.createElement('style');
  css.textContent = 'body{font:14px/1.5 system-ui;color:#e5edf8;background:#0d1724;margin:0}button,select,textarea,input{font:inherit;color:inherit;background:#192c41;border:1px solid #435c77;border-radius:5px;padding:6px}button{cursor:pointer}button:hover{background:#2b4f6e}button:disabled{opacity:.6}header{display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:12px 8px;border-bottom:1px solid #35516b}strong{margin-right:auto}main{padding:12px}h2{font-size:16px}pre,textarea{font:12px/1.5 ui-monospace,Consolas,monospace;background:#081522;padding:12px;border-radius:6px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere}textarea{width:100%;box-sizing:border-box;min-height:130px}pre{max-height:65vh}button.active{background:#236d83}.meta{color:#92aec8;font-size:12px}#message{min-height:19px;color:#a9d8bd}table{width:100%;border-collapse:collapse}th,td{text-align:left;border-bottom:1px solid #34465a;padding:7px}';
  document.head.appendChild(css);
  mount.innerHTML = '<header><strong id="db-title">Документы JSON</strong><span class="meta" id="entry-state">● Приложение запущено из entry</span><button id="add-document">+ Документ</button><button id="edit-document">JSON Patch</button><button id="refresh">Обновить</button></header><main><nav id="document-nav"></nav><p id="message" role="status"></p><section id="new-document" hidden><h2>Новый документ</h2><label>Имя документа <input id="new-document-name" autocomplete="off"></label><p>Начальное JSON-состояние</p><textarea id="new-document-json" spellcheck="false">{}</textarea><p><button id="create-document">Создать документ</button><button id="cancel-create">Отмена</button></p></section><section id="editor" hidden><h2>Изменить документ · RFC 6902</h2><textarea id="patch" spellcheck="false">[{"op":"add","path":"/example","value":1}]</textarea><p><button id="write">Записать</button><button id="cancel">Отмена</button></p></section><h2 id="document-title">Корневой документ</h2><pre id="json"></pre></main>';
  const $ = id => document.getElementById(id);
  let current = '';
  const msg=(text,bad=false)=>{$('message').textContent=text;$('message').style.color=bad?'#ffa4a4':'#9bd9b8';};
  const nav = $('document-nav');
  async function draw() {
    const root=await db.read('');
    $('db-title').textContent=root.name||'JSON DB';
    nav.replaceChildren();
    const names=['',...Object.keys(root.$refs||{})];
    if(!names.includes(current))current='';
    for(const name of names){const b=document.createElement('button');b.textContent=name||'⌂ Корень';b.className=name===current?'active':'';b.style.margin='0 6px 6px 0';b.addEventListener('click',()=>{current=name;draw().catch(e=>msg(e.message,true));});nav.appendChild(b);}
    $('document-title').textContent=current||'Корневой JSON · исходный код entry скрыт';
    const visible=current?await db.read(current+'/'):JSON.parse(JSON.stringify(root));
    if(!current&&visible.entry&&visible.entry.type==='application/javascript'&&typeof visible.entry.source==='string'){
      visible.entry.source='[JS-код скрыт в рабочем представлении; полный исходный текст — в системной «Отладка»]';
    }
    $('json').textContent=JSON.stringify(visible,null,2);
  }
  $('add-document').onclick=()=>{$('new-document').hidden=!$('new-document').hidden;if(!$('new-document').hidden)$('new-document-name').focus();};
  $('cancel-create').onclick=()=>{$('new-document').hidden=true;};
  $('create-document').onclick=async()=>{try{
    const name=$('new-document-name').value.trim();
    if(!name)throw Error('Введите имя нового документа');
    const state=JSON.parse($('new-document-json').value);
    await db.createDocument(name,state);
    current=name;$('new-document').hidden=true;$('new-document-name').value='';$('new-document-json').value='{}';
    await draw();msg('Документ создан');
  }catch(e){msg(e.message,true);}};
  $('edit-document').onclick=()=>{$('editor').hidden=!$('editor').hidden;};
  $('cancel').onclick=()=>{$('editor').hidden=true;};
  $('write').onclick=async()=>{try{await db.patch(current,JSON.parse($('patch').value));$('editor').hidden=true;await draw();msg('Изменение записано. Сохраните HTML в системной строке.');}catch(e){msg(e.message,true);}};
  $('refresh').onclick=()=>draw().catch(e=>msg(e.message,true));
  await draw();
  msg('Приложение из entry успешно запущено. Выберите документ или создайте новый.');
}

/* HTML_DBMS/4 — standalone JSON temporal store. No legacy compatibility. */
(function (g) {
'use strict';
const VERSION = 'HTML_DBMS/4';
const encoder = new TextEncoder(), decoder = new TextDecoder('utf-8', {fatal:true});
const subtle = g.crypto?.subtle || (typeof require === 'function' ? require('node:crypto').webcrypto.subtle : null);
const MAX_RECORDS = 200000, MAX_BYTES = 12 * 1024 * 1024, MAX_PATCH = 10000, MAX_DEPTH = 32;
const own = (o,k) => Object.prototype.hasOwnProperty.call(o,k);
function error(code, message, more={}) { return Object.assign(new Error(message), {code, ...more}); }
function ensure(ok, code, message) { if (!ok) throw error(code, message); }
function plain(x) { return x !== null && typeof x === 'object' && !Array.isArray(x) && (Object.getPrototypeOf(x) === Object.prototype || Object.getPrototypeOf(x) === null); }
function assertJson(x, seen=new Set(), depth=0) {
  ensure(depth<=MAX_DEPTH, 'INVALID_JSON', 'JSON depth exceeded');
  if(x===null || typeof x==='string' || typeof x==='boolean') return;
  if(typeof x==='number') { ensure(Number.isFinite(x), 'INVALID_JSON','Non-finite number');return; }
  ensure(Array.isArray(x)||plain(x),'INVALID_JSON','Only JSON values allowed');
  ensure(!seen.has(x),'INVALID_JSON','Cyclic value');seen.add(x);
  if(Array.isArray(x)) { ensure(Reflect.ownKeys(x).length===x.length+1,'INVALID_JSON','Sparse or decorated array');for(let i=0;i<x.length;i++){const d=Object.getOwnPropertyDescriptor(x,i);ensure(d&&own(d,'value')&&d.enumerable,'INVALID_JSON','Sparse array or accessor');assertJson(d.value,seen,depth+1);} }
  else {ensure(Reflect.ownKeys(x).every(k=>typeof k==='string'), 'INVALID_JSON', 'Symbol property');for(const k of Object.keys(x)) { const d=Object.getOwnPropertyDescriptor(x,k);ensure(d&&own(d,'value')&&d.enumerable,'INVALID_JSON','Accessors forbidden');assertJson(d.value,seen,depth+1);}ensure(Reflect.ownKeys(x).length===Object.keys(x).length,'INVALID_JSON','Hidden property');}
  seen.delete(x);
}
function clone(x){assertJson(x);return JSON.parse(JSON.stringify(x));}
function encode64(b){if(typeof Buffer!=='undefined')return Buffer.from(b).toString('base64url');let s='';for(const n of b)s+=String.fromCharCode(n);return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
function decode64(s){ensure(typeof s==='string'&&/^[A-Za-z0-9_-]*$/.test(s)&&s.length%4!==1,'INVALID_BASE64','Invalid Base64url');let b;if(typeof Buffer!=='undefined') b=new Uint8Array(Buffer.from(s,'base64url'));else{const v=atob(s.replace(/-/g,'+').replace(/_/g,'/')+'='.repeat((4-s.length%4)%4));b=Uint8Array.from(v,c=>c.charCodeAt(0));}ensure(encode64(b)===s,'INVALID_BASE64','Non-canonical Base64url');return b;}
function validId(s){try{return decode64(s).length===16;}catch{return false;}}
function componentBytes(value,size){const bytes=typeof value==='string'?decode64(value):value;ensure(bytes instanceof Uint8Array&&bytes.length===size,'INVALID_HEAD','Invalid HEAD component');return bytes;}
function packHead(id,hash){const b=new Uint8Array(48);b.set(componentBytes(id,16));b.set(componentBytes(hash,32),16);return encode64(b);}
function unpackHead(head){ensure(validHead(head),'INVALID_HEAD','Invalid HEAD');const bytes=decode64(head);ensure(bytes.length===48,'INVALID_HEAD','Invalid HEAD bytes');const idBytes=bytes.slice(0,16),hashBytes=bytes.slice(16);return {idBytes,hashBytes,id:encode64(idBytes),hash:encode64(hashBytes)};}
// 64 base64url symbols encode exactly 48 bytes, with no unused bits.
function validHead(h){return typeof h==='string'&&h.length===64&&/^[A-Za-z0-9_-]{64}$/.test(h);}
function sameHead(a,b){return validHead(a)&&a===b;}
function physicalId(h){return unpackHead(h).id;}
async function sha(b){return new Uint8Array(await subtle.digest('SHA-256',b));}
async function rootId(hash){return encode64((await sha(decode64(hash))).slice(0,16));}
async function successorId(prev){ensure(validHead(prev),'INVALID_HEAD','Invalid predecessor head');const b=decode64(prev);return encode64((await sha(b)).slice(0,16));}
function ivFrom(id){return decode64(id).slice(0,12);}
async function encodeRecord(record){assertJson(record);const bytes=encoder.encode(JSON.stringify(record));ensure(bytes.length<=MAX_BYTES,'RESOURCE_LIMIT','Record too large');return {bytes,h:await sha(bytes)};}
async function encrypt(bytes,h,id){const aes=await subtle.importKey('raw',h,'AES-GCM',false,['encrypt']);const data=new Uint8Array(await subtle.encrypt({name:'AES-GCM',iv:ivFrom(id),tagLength:128},aes,bytes));return encode64(data);}
async function decrypt(ct,{idBytes,hash,hashBytes:h}){let data=decode64(ct);ensure(data.length>=16&&data.length<=MAX_BYTES+16,'RESOURCE_LIMIT','Bad ciphertext length');const aes=await subtle.importKey('raw',h,'AES-GCM',false,['decrypt']);let plaintext;try{plaintext=new Uint8Array(await subtle.decrypt({name:'AES-GCM',iv:idBytes.subarray(0,12),tagLength:128},aes,data));}catch{throw error('INVALID_GCM','Authentication failed');}
ensure(encode64(await sha(plaintext))===hash,'HASH_MISMATCH','Hash mismatch');let r;try{r=JSON.parse(decoder.decode(plaintext));}catch{throw error('INVALID_JSON','Invalid record JSON');}assertJson(r);return r;}
function validCipher(id,ct){
 ensure(typeof id==='string'&&id.length===22&&validId(id)&&typeof ct==='string'&&ct.length>=22&&ct.length<=Math.ceil((MAX_BYTES+16)*4/3)&&!/[^A-Za-z0-9_-]/.test(ct)&&ct.length%4!==1,'INVALID_RECORD','Invalid physical record');
 const rem=ct.length%4;ensure(!rem||(rem===2?/^[AQgw]$/:/^[AEIMQUYcgkosw048]$/).test(ct.at(-1)),'INVALID_RECORD','Noncanonical ciphertext');
}
function validPublication(name,head){ensure(typeof name==='string'&&name.length>0&&validHead(head),'INVALID_PUBLIC_HEADS','Invalid public head: '+String(name));}
function dataKeys(o){
 ensure(plain(o),'INVALID_JSON','Expected object');
 const keys=Reflect.ownKeys(o);for(const k of keys){const d=Object.getOwnPropertyDescriptor(o,k);ensure(typeof k==='string'&&d.enumerable&&own(d,'value'),'INVALID_JSON','Non-data property');}return keys;
}
function validateStore(s){
 ensure(plain(s)&&own(s,'format')&&own(s,'records'),'UNSUPPORTED_STORAGE','Expected HTML_DBMS/4');
 ensure(dataKeys(s).every(k=>['format','publicHeads','records'].includes(k))&&s.format===VERSION&&plain(s.records),'UNSUPPORTED_STORAGE','Expected HTML_DBMS/4');
 if(own(s,'publicHeads'))for(const n of dataKeys(s.publicHeads))validPublication(n,s.publicHeads[n]);
 const ids=dataKeys(s.records);ensure(ids.length<=MAX_RECORDS,'RESOURCE_LIMIT','Too many records');for(const id of ids)validCipher(id,s.records[id]);return s;
}
// Only these controlled stores are mutable. External containers are adopted once.
// Overlay reads are revision-bound; a stale transaction cannot read a mixed snapshot.
const stores=new WeakMap(),REMOVED=Symbol('removed');
function fresh(m){ensure(!m.closed&&(!m.base||m.base.rev===m.baseRev),'STALE_TRANSACTION','Store revision changed');}
function meta(s){const m=stores.get(s);ensure(m,'UNMANAGED_STORE','Adopt external storage before mutation');fresh(m);return m;}
function revision(s){return meta(s).rev;}
function unchanged(s,rev){if(rev!==undefined)ensure(revision(s)===rev,'STALE_TRANSACTION','Store revision changed');}
function beginRead(s){if(stores.has(s))return revision(s);validateStore(s);}
function guardedMap(m,kind){
 const records=kind==='records',target=Object.create(null);
 const backing=()=>records?(m.base?m.base.raw:m.raw):m.catalog;
 const has=k=>{fresh(m);return records&&m.delta?.has(k)?m.delta.get(k)!==REMOVED:own(backing(),k);};
 const get=k=>{fresh(m);return records&&m.delta?.has(k)?(m.delta.get(k)===REMOVED?undefined:m.delta.get(k)):backing()[k];};
 const keys=()=>{fresh(m);if(!records||!m.delta)return Object.keys(backing());const result=new Set(Object.keys(backing()));for(const [k,v] of m.delta)v===REMOVED?result.delete(k):result.add(k);return [...result];};
 const set=(k,v)=>{fresh(m);if(records){validCipher(k,v);if(!has(k)){ensure(m.count<MAX_RECORDS,'RESOURCE_LIMIT','Too many records');m.count++;}if(m.delta)m.delta.set(k,v);else put(m.raw,k,v);m.proof=null;}else{validPublication(k,v);put(m.catalog,k,v);}m.rev++;return true;};
 return new Proxy(target,{
  get:(_,k)=>get(k),has:(_,k)=>has(k),ownKeys:keys,
  getOwnPropertyDescriptor:(_,k)=>has(k)?{value:get(k),enumerable:true,writable:true,configurable:true}:undefined,
  set:(_,k,v)=>set(k,v),
  defineProperty:(_,k,d)=>{ensure(own(d,'value')&&d.enumerable===true&&d.configurable===true&&d.writable===true,'INVALID_JSON','Only writable data properties');return set(k,d.value);},
  deleteProperty:(_,k)=>{fresh(m);if(has(k)){if(records){m.count--;if(m.delta)m.delta.set(k,REMOVED);else delete m.raw[k];m.proof=null;}else delete m.catalog[k];m.rev++;}return true;},
  setPrototypeOf:()=>false,preventExtensions:()=>false
 });
}
function catalogFrom(value){const out=Object.create(null);for(const k of dataKeys(value)){validPublication(k,value[k]);put(out,k,value[k]);}return out;}
function makeStore(m){
 const target={format:VERSION,records:guardedMap(m,'records')};m.target=target;
 if(m.catalog)target.publicHeads=guardedMap(m,'catalog');
 // Retain canonical property order for newly created stores and generated artifacts.
 const ordered={format:VERSION};if(m.catalog)ordered.publicHeads=target.publicHeads;ordered.records=target.records;m.target=ordered;
 const proxy=new Proxy(ordered,{
  get:(t,k)=>{fresh(m);return Reflect.get(t,k);},
  ownKeys:t=>{fresh(m);return Reflect.ownKeys(t);},
  getOwnPropertyDescriptor:(t,k)=>{fresh(m);return Reflect.getOwnPropertyDescriptor(t,k);},
  set:(t,k,v)=>{fresh(m);ensure(k==='publicHeads','INVALID_JSON','Store fields are controlled');m.catalog=catalogFrom(v);t.publicHeads=guardedMap(m,'catalog');m.rev++;return true;},
  deleteProperty:(t,k)=>{fresh(m);ensure(k==='publicHeads','INVALID_JSON','Store fields are controlled');if(m.catalog){m.catalog=null;delete t.publicHeads;m.rev++;}return true;},
  defineProperty:()=>false,setPrototypeOf:()=>false,preventExtensions:()=>false
 });stores.set(proxy,m);return proxy;
}
function adoptStore(s){
 validateStore(s);
 const raw=Object.assign(Object.create(null),s.records);
 return makeStore({raw,count:Object.keys(raw).length,catalog:own(s,'publicHeads')?catalogFrom(s.publicHeads):null,rev:0});
}
function newStore(){return makeStore({raw:Object.create(null),count:0,catalog:Object.create(null),rev:0});}
function iso(s){return typeof s==='string'&&/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d\.\d{3}Z$/.test(s)&&!Number.isNaN(Date.parse(s))&&new Date(s).toISOString()===s;}
// Compact v4 format: genesis = [null,{name,parent,state}], patch = [ISO-time,previousHEAD,RFC6902-operations].
// Sequence is derived from verified ancestry; it is NEVER serialized.
function isGenesis(r){return Array.isArray(r)&&r.length===2&&r[0]===null;}
function validateRecord(r){
 assertJson(r);ensure(Array.isArray(r),'INVALID_EVENT','Record must be array');
 if(isGenesis(r)){
  const v=r[1];ensure(plain(v)&&typeof v.name==='string'&&v.name.trim()&&(v.parent===null||validHead(v.parent))&&own(v,'state'),'INVALID_GENESIS','Invalid genesis');
  ensure(Object.keys(v).length===3&&['name','parent','state'].every(k=>own(v,k)),'INVALID_GENESIS','Genesis fields');
 }else{
  ensure(r.length===3&&iso(r[0])&&validHead(r[1])&&Array.isArray(r[2])&&r[2].length>=1&&r[2].length<=MAX_PATCH,'INVALID_EVENT','Invalid patch header');
 }
 return r;
}
async function expectedId(r,hash){return isGenesis(r)?rootId(hash):successorId(r[1]);}
async function readDecoded(s,decoded){const {id,hash}=decoded;ensure(own(s.records,id),'MISSING_RECORD','Missing record '+id);let r=validateRecord(await decrypt(s.records[id],decoded));ensure((await expectedId(r,hash))===id,'ADDRESS_MISMATCH','Wrong physical address');return r;}
async function readRecord(s,head){const rev=stores.has(s)?revision(s):undefined;const r=await readDecoded(s,unpackHead(head));unchanged(s,rev);return r;}
function parts(pointer){ensure(typeof pointer==='string'&&(pointer===''||pointer[0]==='/'),'INVALID_POINTER','Not a JSON Pointer');if(pointer==='')return [];return pointer.slice(1).split('/').map(s=>{ensure(!/~(?![01])/.test(s),'INVALID_POINTER','Invalid tilde escape');return s.replace(/~1/g,'/').replace(/~0/g,'~');});}
function indexOfToken(t,len,insert=false){ensure(t==='-'&&insert||/^(0|[1-9]\d*)$/.test(t),'INVALID_POINTER','Invalid array index');if(t==='-')return len;const i=Number(t);ensure(Number.isSafeInteger(i)&&i<=(insert?len:len-1),'INVALID_POINTER','Array index out of bounds');return i;}
function jsonEqual(a,b){
 if(a===b)return true;
 if(a===null||b===null||typeof a!==typeof b||typeof a!=='object')return false;
 if(Array.isArray(a)||Array.isArray(b))return Array.isArray(a)&&Array.isArray(b)&&a.length===b.length&&a.every((v,i)=>jsonEqual(v,b[i]));
 if(!plain(a)||!plain(b))return false;
 const ak=Object.keys(a),bk=Object.keys(b);
 return ak.length===bk.length&&ak.every(k=>own(b,k)&&jsonEqual(a[k],b[k]));
}
function atPath(obj,tokens){let x=obj;for(const t of tokens){if(Array.isArray(x)){x=x[indexOfToken(t,x.length)];}else{ensure(plain(x)&&own(x,t),'INVALID_POINTER','Missing JSON Pointer target');x=x[t];}}return x;}
function put(target,k,v){Object.defineProperty(target,k,{value:v,writable:true,enumerable:true,configurable:true});}
function parentAndKey(obj,tokens){ensure(tokens.length>0,'INVALID_POINTER','Root target needs special handling');return [atPath(obj,tokens.slice(0,-1)),tokens.at(-1)];}
function patch(json,ops){assertJson(json);assertJson(ops);ensure(Array.isArray(ops)&&ops.length>=1&&ops.length<=MAX_PATCH,'INVALID_PATCH','Patch must contain an operation');let out=clone(json);
 for(const op of ops){ensure(plain(op)&&typeof op.op==='string'&&typeof op.path==='string','INVALID_PATCH','Malformed JSON Patch operation');const dest=parts(op.path);if(op.op==='test'){ensure(own(op,'value')&&jsonEqual(atPath(out,dest),op.value),'INVALID_PATCH','Test failed');continue;}
 let value;if(op.op==='add'||op.op==='replace') {ensure(own(op,'value'),'INVALID_PATCH','Missing value');value=clone(op.value);}else if(op.op==='copy'||op.op==='move'){ensure(typeof op.from==='string','INVALID_PATCH','Missing from');const src=parts(op.from);ensure(op.op!=='move'||!(dest.length>src.length&&src.every((t,i)=>t===dest[i])),'INVALID_PATCH','Move into descendant');value=clone(atPath(out,src));if(op.op==='move')out=remove(out,src);}else if(op.op!=='remove')throw error('INVALID_PATCH','Unknown operation');
 if(op.op==='remove'){out=remove(out,dest);continue;}
 if(op.op==='replace') atPath(out,dest);
 if(dest.length===0){out=value;continue;}
 const [p,k]=parentAndKey(out,dest);if(Array.isArray(p)){if(op.op==='replace')p[indexOfToken(k,p.length)]=value;else p.splice(indexOfToken(k,p.length,true),0,value);}else{ensure(plain(p),'INVALID_POINTER','Parent is not object');put(p,k,value);}
 }assertJson(out);return out;}
function remove(out,tokens){if(!tokens.length)return null;const [p,k]=parentAndKey(out,tokens);if(Array.isArray(p))p.splice(indexOfToken(k,p.length),1);else{ensure(plain(p)&&own(p,k),'INVALID_POINTER','Missing remove target');delete p[k];}return out;}
function diagnose(e,head,events=[]){return {status:'broken',code:e.code||'INVALID_CHAIN',message:e.message||String(e),sourceHead:validHead(head)?head:null,tailIds:events.map(x=>physicalId(x.head))};}
async function inspect(s,head,limit=MAX_RECORDS){return inspectChain(s,head,limit);}
async function inspectChain(s,head,limit=MAX_RECORDS,visit){try{if(!stores.has(s))s=adoptStore(s);const revisionAtStart=beginRead(s);ensure(validHead(head),'INVALID_HEAD','Head required');const rev=[],seen=new Set();let h=head;while(true){const decoded=unpackHead(h);ensure(!seen.has(decoded.id),'CYCLE','Cycle in physical chain');seen.add(decoded.id);ensure(rev.length<limit,'RESOURCE_LIMIT','Chain too long');let r;try{r=await readDecoded(s,decoded);unchanged(s,revisionAtStart);}catch(e){const d=diagnose(e,head,rev);d.invalid=h;d.tailIds=[decoded.id,...d.tailIds];d.recoveryHead=null;return d;}
 rev.push({head:h,r});if(isGenesis(r))break;h=r[1];}
const events=rev.reverse();let state=clone(events[0].r[1].state);if(visit)visit(state,events[0].head,false);for(let i=1;i<events.length;i++){try{state=patch(state,events[i].r[2]);}catch(e){const d=diagnose(e,head,events.slice(i));d.invalid=events[i].head;return d;}if(visit)visit(state,events[i-1].head,true);}
unchanged(s,revisionAtStart);return {status:'complete',chain:{head,genesis:clone(events[0].r[1]),state,events}};
}catch(e){return diagnose(e,head);}}
async function load(s,head){return loadChain(s,head);}
async function loadChain(s,head,visit){const x=await inspectChain(s,head,MAX_RECORDS,visit);if(x.status!=='complete')throw error(x.code,x.message,{diagnosis:x});return x.chain;}
async function genesis(s,name,state,parent=null,options={}){const rev=revision(s),overwrite=!!options.overwrite;ensure(typeof name==='string'&&name.trim(),'INVALID_NAME','Document name required');ensure(parent===null||validHead(parent),'INVALID_HEAD','Invalid genesis parent');const r=validateRecord([null,{name,parent:parent===null?null:clone(parent),state:clone(state)}]);const {bytes,h}=await encodeRecord(r),id=encode64((await sha(h)).slice(0,16));const occupied=own(s.records,id);if(occupied&&!overwrite){const old=await readRecord(s,packHead(id,h)).catch(()=>null);unchanged(s,rev);if(old&&JSON.stringify(old)===JSON.stringify(r))return {head:packHead(id,h),existing:true,overwritten:false};throw error('ROOT_OCCUPIED','Genesis slot occupied');}
const ciphertext=await encrypt(bytes,h,id);unchanged(s,rev);s.records[id]=ciphertext;return {head:packHead(id,h),existing:false,overwritten:occupied};}
async function append(s,head,operations,options={}){const rev=revision(s),ops=clone(operations),opts={overwrite:!!options.overwrite,timestamp:options.timestamp},chain=await load(s,head);return appendKnown(s,head,chain.state,ops,opts,rev);}
